 10	/// Offline resolver with an explicitly configured statistical scorer.
 11	pub struct DeclarationResolverService<S, F> {
 12	    storage: S,
 13	    scorer: F,
 14	    candidate_budget: usize,
 15	}
 16	impl<S: DeclarationResolutionStorage, F: FunderScorer> DeclarationResolverService<S, F> {
 17	    /// Supplies storage, scorer and the maximum candidate count.
 18	    #[must_use]
 19	    pub const fn new(storage: S, scorer: F, candidate_budget: usize) -> Self {
 20	        Self {
 21	            storage,
 22	            scorer,
 23	            candidate_budget,
 24	        }
 25	    }
 26	    /// Resolves and publishes one ingestion run.
 27	    ///
 28	    /// # Errors
 29	    /// Fails on incoherent evidence, scorer errors, budget refusal, or publication errors.
 30	    pub async fn resolve_declarations(
 31	        &self,
 32	    ) -> Result<DeclarationResolutionSummary, EntityIngestionError> {
 33	        let input = self.storage.read_resolution_input().await?;
 34	        let scoring = input.scoring_input(self.candidate_budget);
 35	        let scored = self.scorer.score(&scoring).await?;
 36	        let result = ResolvedDeclarations::from_scored(
 37	            &input,
 38	            &scoring,
 39	            scored,
 40	            &self.storage.resolution_run_key(),
 41	        )?;
 42	        self.storage.publish_resolution(&result).await?;
 43	        Ok(result.summary())
 44	    }
 45	}
