189	impl ResolvedDeclarations {
190	    /// Applies conservative identity links and the independent payment-role policy.
191	    ///
192	    /// # Errors
193	    /// Refuses expansion of repeated profiles beyond the configured candidate budget.
194	    pub fn from_scored(
195	        input: &ResolutionInput,
196	        scoring: &ScoringInput,
197	        scored: ScoredPairs,
198	        run_key: &str,
199	    ) -> Result<Self, EntityIngestionError> {
200	        let (observations, pairs) = identity::resolve(input, scoring, scored.pairs, run_key)?;
201	        let attributions = input
202	            .payments
203	            .values()
204	            .map(|payment| attribute(input, payment))
205	            .collect::<Vec<_>>();
206	        let manifest = serde_json::json!({ "schema_version":1, "rust_package_version":env!("CARGO_PKG_VERSION"), "policy_version":POLICY_VERSION, "automatic_threshold":AUTOMATIC_THRESHOLD,
207	            "input_sha256":input.digests, "model":scored.model, "scoring_profiles":scoring.rows.len(), "observations":observations.len(), "payments":attributions.len(),
208	            "pair_decisions":pairs.len(), "accepted_pairs":pairs.iter().filter(|p|p.disposition==PairDisposition::Accepted).count(),
209	            "review_pairs":pairs.iter().filter(|p|p.disposition==PairDisposition::Review).count(), "candidate_budget":scoring.candidate_budget,
210	            "identity_scope":"run-local IDs use ingestion key and lexicographically first component member; changed membership can change IDs; cross-run reconciliation unsupported" });
211	        Ok(Self {
212	            observations,
213	            attributions,
214	            pairs,
215	            manifest,
216	        })
217	    }
218	
219	    /// Row counts of the complete result.
220	    #[must_use]
221	    pub const fn summary(&self) -> DeclarationResolutionSummary {
222	        DeclarationResolutionSummary {
223	            observations: self.observations.len(),
224	            payments: self.attributions.len(),
225	            pairs: self.pairs.len(),
226	        }
227	    }
228	}
