    35	impl DeclarationResolutionStorage for ExposedDataPipeline {
    36	    async fn read_resolution_input(&self) -> Result<ResolutionInput, EntityIngestionError> {
    37	        let destination = self.resolved_declarations_path();
    38	        if fs::try_exists(&destination).await.map_err(read_error)? {
    39	            return Err(write_error("resolved declarations already exist").into());
    40	        }
    41	        let directory = self.cleaned_declarations_path();
    42	        let (observations, observation_digest) =
    43	            read_table::<Observation>(&directory.join("funders.parquet"), &funders_schema())?;
    44	        let (payments, payment_digest) = read_table::<Payment>(
    45	            &directory.join("funding_entries.parquet"),
    46	            &funding_schema(),
    47	        )?;
    48	        ResolutionInput::new(
    49	            observations,
    50	            payments,
    51	            BTreeMap::from([
    52	                ("funders.parquet".into(), observation_digest),
    53	                ("funding_entries.parquet".into(), payment_digest),
    54	            ]),
    55	        )
    56	    }
    57	    fn resolution_run_key(&self) -> String {
    58	        crate::domain::models::entity_ingestion::IngestionKey::from(self.key()).to_string()
    59	    }
    60	    async fn publish_resolution(
    61	        &self,
    62	        result: &ResolvedDeclarations,
    63	    ) -> Result<(), EntitySearchPipelineError> {
    64	        let destination = self.resolved_declarations_path();
    65	        let parent = destination
    66	            .parent()
    67	            .expect("resolved declarations have a parent");
    68	        fs::create_dir_all(parent).await.map_err(write_error)?;
    69	        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
    70	        let publication = async {
    71	            if fs::try_exists(&destination).await.map_err(write_error)? {
    72	                return Err(write_error("resolved declarations already exist"));
    73	            }
    74	            fs::create_dir(&staging).await.map_err(write_error)?;
    75	            write_table(
    76	                &staging.join("observation_resolution.parquet"),
    77	                observation_schema(),
    78	                &result.observations,
    79	            )
    80	            .await?;
    81	            write_table(
    82	                &staging.join("payment_attribution.parquet"),
    83	                attribution_schema(),
    84	                &result.attributions,
    85	            )
    86	            .await?;
    87	            write_table(
    88	                &staging.join("pair_decisions.parquet"),
    89	                pair_schema(),
    90	                &result.pairs,
    91	            )
    92	            .await?;
    93	            fs::write(
    94	                staging.join("manifest.json"),
    95	                serde_json::to_vec_pretty(&result.manifest).map_err(write_error)?,
    96	            )
    97	            .await
    98	            .map_err(write_error)?;
    99	            publish_directory(&staging, &destination).map_err(write_error)
   100	        }
   101	        .await;
   102	        if publication.is_err() {
   103	            let _ = fs::remove_dir_all(&staging).await;
   104	        }
   105	        publication
   106	    }
   107	}
