   109	pub(super) fn read_table<T: DeserializeOwned>(
   110	    path: &Path,
   111	    expected: &Schema,
   112	) -> Result<(Vec<T>, String), EntitySearchPipelineError> {
   113	    let bytes = std::fs::read(path).map_err(read_error)?;
   114	    let digest = format!("{:x}", Sha256::digest(&bytes));
   115	    let reader =
   116	        ParquetRecordBatchReaderBuilder::try_new(bytes::Bytes::from(bytes)).map_err(read_error)?;
   117	    for required in expected.fields() {
   118	        let actual=reader.schema().field_with_name(required.name()).map_err(|_|read_error("cleaned declarations lack the resolution schema; clean the retained raw capture into a fresh ingestion run"))?;
   119	        if actual.data_type() != required.data_type()
   120	            || actual.is_nullable() != required.is_nullable()
   121	        {
   122	            return Err(read_error(format!(
   123	                "cleaned field {} has an incompatible type; clean retained raw into a fresh run",
   124	                required.name()
   125	            )));
   126	        }
   127	    }
   128	    let mut rows = Vec::new();
   129	    for batch in reader.build().map_err(read_error)? {
   130	        let mut writer = ArrayWriter::new(Vec::new());
   131	        writer
   132	            .write(&batch.map_err(read_error)?)
   133	            .map_err(read_error)?;
   134	        writer.finish().map_err(read_error)?;
   135	        rows.extend(serde_json::from_slice::<Vec<T>>(&writer.into_inner()).map_err(read_error)?);
   136	    }
   137	    Ok((rows, digest))
   138	}
