   145	impl SplinkScorer {
   146	    /// Selects the interpreter and the separately installed worker script.
   147	    ///
   148	    /// # Errors
   149	    /// Returns an error when the configured worker cannot be read.
   150	    pub fn new(python: PathBuf, worker: PathBuf) -> Result<Self, EntityIngestionError> {
   151	        if !worker.is_file() {
   152	            return Err(EntityIngestionError::DataError(format!(
   153	                "Splink worker missing at {}; configure resolution_worker",
   154	                worker.display()
   155	            )));
   156	        }
   157	        Ok(Self { python, worker })
