   160	#[derive(Deserialize)]
   161	struct WorkerOutput {
   162	    version: u32,
   163	    model: serde_json::Value,
   164	    pairs: Vec<ScoredPair>,
   165	}
   166	impl FunderScorer for SplinkScorer {
   167	    async fn score(&self, input: &ScoringInput) -> Result<ScoredPairs, EntityIngestionError> {
   168	        let encoded = serde_json::to_vec(input)
   169	            .map_err(|e| EntityIngestionError::DataError(e.to_string()))?;
   170	        let python = self.python.clone();
   171	        let worker = self.worker.clone();
   172	        let output=tokio::task::spawn_blocking(move || -> Result<WorkerOutput,EntityIngestionError> {
   173	            let temporary=tempfile::tempdir().map_err(|e|EntityIngestionError::DataError(e.to_string()))?;
   174	            let request=temporary.path().join("input.json"); let response=temporary.path().join("output.json");
   175	            std::fs::write(&request,encoded).map_err(|e|EntityIngestionError::DataError(e.to_string()))?;
   176	            let process=Command::new(&python).arg(&worker).arg(&request).arg(&response).env("PYTHONDONTWRITEBYTECODE","1").output().map_err(|e|EntityIngestionError::DataError(format!("cannot run Splink interpreter {}: {e}; install resolution dependencies before running resolve",python.display())))?;
   177	            if !process.status.success() { return Err(EntityIngestionError::DataError(format!("Splink worker failed ({}): {}",process.status,String::from_utf8_lossy(&process.stderr)))); }
   178	            let bytes=std::fs::read(&response).map_err(|e|EntityIngestionError::DataError(format!("Splink worker output missing: {e}")))?;
   179	            serde_json::from_slice(&bytes).map_err(|e|EntityIngestionError::DataError(format!("invalid Splink worker output: {e}")))
   180	        }).await.map_err(|e|EntityIngestionError::DataError(e.to_string()))??;
   181	        let expected: serde_json::Value = serde_json::from_str(include_str!(concat!(
   182	            env!("CARGO_MANIFEST_DIR"),
   183	            "/../resolution/exposed_resolution/model.json"
   184	        )))
   185	        .map_err(|error| {
   186	            EntityIngestionError::DataError(format!("invalid bundled frozen model: {error}"))
   187	        })?;
   188	        if output.version != 1
   189	            || [
   190	                "model_version",
   191	                "splink_version",
   192	                "duckdb_version",
   193	                "calibrated",
   194	                "settings",
   195	            ]
   196	            .iter()
   197	            .any(|key| output.model[*key] != expected[*key])
   198	            || output.model["python_version"]
   199	                .as_str()
   200	                .is_none_or(str::is_empty)
   201	        {
   202	            return Err(EntityIngestionError::DataError(
   203	                "unsupported Splink protocol, frozen model, or runtime version".into(),
   204	            ));
   205	        }
   206	
   207	        ScoredPairs::checked(output.pairs, output.model, input)
   208	    }
   209	}
