    50	impl ResolutionInput {
    51	    pub(crate) fn new(
    52	        observations: Vec<Observation>,
    53	        payments: Vec<Payment>,
    54	        digests: BTreeMap<String, String>,
    55	    ) -> Result<Self, EntityIngestionError> {
    56	        let mut input = Self {
    57	            observations: BTreeMap::new(),
    58	            payments: BTreeMap::new(),
    59	            digests,
    60	        };
    61	        let mut members = BTreeMap::new();
    62	        let mut declarations = BTreeMap::new();
    63	        for payment in payments {
    64	            check_payment(&payment, &mut members, &mut declarations)?;
    65	            if input
    66	                .payments
    67	                .insert(payment.funding_entry_id.clone(), payment)
    68	                .is_some()
