    70	                return Err(invalid("duplicate funding occurrence ID"));
    71	            }
    72	        }
    73	        for observation in observations {
    74	            check_observation(&observation, &input, &mut declarations)?;
    75	            if input
    76	                .observations
    77	                .insert(observation.funder_id.clone(), observation)
    78	                .is_some()
    79	            {
    80	                return Err(invalid("duplicate funder observation ID"));
    81	            }
    82	        }
    83	        for payment in input.payments.values() {
    84	            for (id, role) in [
    85	                (&payment.donor_funder_id, FunderRole::Donor),
    86	                (&payment.payer_funder_id, FunderRole::Payer),
    87	                (&payment.ultimate_payer_funder_id, FunderRole::UltimatePayer),
