   118	    /// Groups repeated feature profiles without asserting that they identify the same funder.
   119	    #[must_use]
   120	    pub fn scoring_input(&self, candidate_budget: usize) -> ScoringInput {
   121	        let mut groups = BTreeMap::<(String, Option<String>), Vec<FunderObservationId>>::new();
   122	        for observation in self.observations.values() {
   123	            if let Some(name) = &observation.name_normalized {
   124	                groups
   125	                    .entry((name.clone(), observation.address_normalized.clone()))
   126	                    .or_default()
   127	                    .push(observation.funder_id.clone());
   128	            }
   129	        }
   130	        let mut rows = Vec::new();
   131	        let mut members = BTreeMap::new();
   132	        for (index, ((name, address), ids)) in groups.into_iter().enumerate() {
   133	            let key = format!("profile-{index:08}");
   134	            rows.push(ComparisonRow {
   135	                key: key.clone(),
   136	                name: name.clone(),
   137	                address: address.clone(),
   138	                blocking_keys: ids
   139	                    .iter()
   140	                    .flat_map(|id| blocking_keys(&self.observations[id]))
   141	                    .collect::<BTreeSet<_>>()
   142	                    .into_iter()
   143	                    .collect(),
   144	                needs_resolution: ids
   145	                    .iter()
   146	                    .any(|id| company(&self.observations[id]).is_none()),
   147	            });
   148	            members.insert(key.clone(), ids.clone());
   149	            if ids.len() > 1
   150	                && ids
   151	                    .iter()
   152	                    .any(|id| company(&self.observations[id]).is_none())
   153	            {
   154	                let copy = format!("{key}-repeat");
   155	                rows.push(ComparisonRow {
   156	                    key: copy.clone(),
   157	                    name,
   158	                    address,
   159	                    blocking_keys: ids
   160	                        .iter()
   161	                        .flat_map(|id| blocking_keys(&self.observations[id]))
   162	                        .collect::<BTreeSet<_>>()
   163	                        .into_iter()
   164	                        .collect(),
   165	                    needs_resolution: true,
   166	                });
   167	                members.insert(copy, ids);
   168	            }
   169	        }
   170	        ScoringInput {
   171	            version: 2,
   172	            candidate_budget,
   173	            rows,
   174	            members,
   175	        }
   176	    }
   177	}
