   179	fn blocking_keys(observation: &Observation) -> BTreeSet<String> {
   180	    let mut keys = observation
   181	        .name_normalized
   182	        .iter()
   183	        .chain(observation.alias_normalized.iter())
   184	        .map(|name| format!("funder-name:{name}"))
   185	        .collect::<BTreeSet<_>>();
   186	    let is_trade_union = observation
   187	        .donor_kind
   188	        .as_deref()
   189	        .is_some_and(|kind| kind.trim().eq_ignore_ascii_case("trade union"));
   190	    let Some(raw) = observation.name_raw.as_deref() else {
   191	        return keys;
   192	    };
   193	    let raw = raw.to_lowercase();
   194	    if is_trade_union
   195	        && raw
   196	            .split(|c: char| !c.is_alphanumeric())
   197	            .any(|token| token == "unite")
   198	    {
   199	        keys.insert("trade-union:unite".to_owned());
   200	    }
   201	    keys
   202	}
