   204	fn root_scope(pointer: &str) -> bool {
   205	    let parts = pointer.split('/').collect::<Vec<_>>();
   206	    parts.len() >= 4
   207	        && parts[0].is_empty()
   208	        && parts[1] == "versions"
   209	        && parts[2].parse::<u32>().is_ok()
   210	        && parts[3] == "fields"
   211	        && (parts.len() - 4).is_multiple_of(3)
   212	        && parts[4..].chunks(3).all(|chunk| {
   213	            chunk[0].parse::<u32>().is_ok()
   214	                && chunk[1] == "values"
   215	                && chunk[2].parse::<u32>().is_ok()
   216	        })
   217	}
   218	pub(super) fn is_root(pointer: &str) -> bool {
   219	    pointer.split('/').count() == 4
   220	}
