   245	#[derive(Deserialize)]
   246	pub struct ScoredPair {
   247	    pub left: String,
   248	    pub right: String,
   249	    pub probability: f64,
   250	    pub name_level: i32,
   251	    pub address_level: i32,
   252	}
   253	impl ScoredPairs {
   254	    pub(crate) fn checked(
   255	        pairs: Vec<ScoredPair>,
   256	        model: serde_json::Value,
   257	        input: &ScoringInput,
   258	    ) -> Result<Self, EntityIngestionError> {
   259	        let mut seen = BTreeSet::new();
   260	        if pairs.len() > input.candidate_budget {
   261	            return Err(invalid("worker exceeded candidate budget"));
   262	        }
   263	        for pair in &pairs {
   264	            if pair.left >= pair.right
   265	                || !input.members.contains_key(&pair.left)
   266	                || !input.members.contains_key(&pair.right)
   267	                || !seen.insert((&pair.left, &pair.right))
   268	            {
   269	                return Err(invalid(
   270	                    "worker returned duplicate, unordered, or unknown profile pair",
   271	                ));
   272	            }
   273	            if !pair.probability.is_finite()
   274	                || !(0.0..=1.0).contains(&pair.probability)
   275	                || !(-1..=2).contains(&pair.name_level)
   276	                || !(-1..=1).contains(&pair.address_level)
   277	            {
   278	                return Err(invalid(
   279	                    "worker returned invalid probability or comparison level",
   280	                ));
   281	            }
   282	        }
   283	        Ok(Self { pairs, model })
   284	    }
   285	}
