   331	fn check_observation(
   332	    observation: &Observation,
   333	    input: &ResolutionInput,
   334	    declarations: &mut DeclarationMetadata,
   335	) -> Result<(), EntityIngestionError> {
   336	    if uuid::Uuid::parse_str(&observation.member_id).map_or(true, |id| id.is_nil())
   337	        || observation.declaration_id == 0
   338	        || observation.register_id == 0
   339	    {
   340	        return Err(invalid("invalid cleaned observation identity"));
   341	    }
   342	    check_scope(observation, input)?;
   343	    if observation.role != FunderRole::Donor
   344	        && (observation.donor_kind.is_some() || observation.donor_company_number.is_some())
   345	    {
   346	        return Err(invalid("payer role carries donor metadata"));
   347	    }
   348	    if observation.address_match_quality
   349	        != AddressMatchQuality::from_normalized(observation.address_normalized.as_deref())
   350	    {
   351	        return Err(invalid(
   352	            "address matching quality disagrees with public evidence",
   353	        ));
   354	    }
   355	    if observation
   356	        .name_normalized
   357	        .as_ref()
   358	        .is_some_and(|name| name.trim().is_empty())
   359	        || observation
   360	            .address_normalized
   361	            .as_ref()
   362	            .is_some_and(|address| address.trim().is_empty())
   363	    {
   364	        return Err(invalid("empty normalized comparison evidence"));
   365	    }
   366	    let role_suffix = match observation.role {
   367	        FunderRole::Donor => "donor",
   368	        FunderRole::Payer => "payer",
   369	        FunderRole::UltimatePayer => "ultimate_payer",
   370	    };
   371	    let scope = observation.funding_entry_id.as_ref().map_or_else(
   372	        || {
   373	            format!(
   374	                "{}/{}/{}/declaration",
   375	                observation.member_id, observation.declaration_id, observation.register_id
   376	            )
   377	        },
   378	        |id| id.as_str().to_owned(),
   379	    );
   380	    if observation.funder_id.as_str() != format!("{scope}/{role_suffix}") {
   381	        return Err(invalid(
   382	            "funder observation ID disagrees with source scope and role",
   383	        ));
   384	    }
   385	    let metadata = declarations
   386	        .entry((observation.member_id.clone(), observation.declaration_id))
   387	        .or_insert((observation.register_id, None));
   388	    if metadata.0 != observation.register_id {
   389	        return Err(invalid("observation declaration register mismatch"));
   390	    }
   391	    Ok(())
   392	}
